def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for fail in failed:
        self.close_failed_request(fail)
        logging.error(f'Request failed: {fail[2]}')
    if not self.running:
        return False
    return True

def _query(self, query):
    old = query.copy()
    self.pre_translation(query)
    if old != query:
        log.debug('RHBugzilla altered query to: %s', query)
    ret = self._proxy.Bug.search(query)
    if self.is_legacy_version():
        for bug in ret['bugs']:
            self.post_translation(query, bug)
    return ret

def is_legacy_version(self):
    return False

