def get_table_resize(table_data, table_col_count, cell_data) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        total_width = sum((cell.estimate_width() for cell in cell_data))
        if total_width >= resizing_px_threshold:
            resize = True
    return resize

def get_table_resize(table_data, table_col_count) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        resizing_px_threshold = 595 - 35
        first_row = table_data.get('rows', [])[0] if table_data.get('rows') else None
        if first_row:
            total_estimated_width = 0
            for cell in first_row.get('cells', []):
                content = cell.get('content', '')
                font_size = cell.get('font_size', 12)
                try:
                    font_size = float(font_size)
                except (TypeError, ValueError):
                    font_size = 12
                total_estimated_width += len(content) * font_size / 2
            if total_estimated_width >= resizing_px_threshold:
                resize = True
        else:
            resizing_col_threshold = 2
            if table_col_count >= resizing_col_threshold:
                resize = True
    return resize

